// Initial document content
const basicDoc = `# Basic Table Preview

This editor uses the default table plugin.

### Table (source on cursor)

| Name  | Age | City     |
|-------|-----|----------|
| Alice | 25  | Beijing  |
| Bob   | 30  | Shanghai |

Click inside the table to switch to Markdown source.`;

